INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das Single Responsibility Principle nur für Klassen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Module oder Funktionen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Single Responsibility Principle?', 3, '[{"text": "Klarheit der Aufgaben", "correct": true, "because": "Eine Verantwortung pro Einheit"}, {"text": "Code kürzen", "correct": false, "because": "Nicht primär"}, {"text": "Performance steigern", "correct": false, "because": "Kein direkter Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Single Responsibility Principle?', 5, '[{"text": "Wartbarkeit", "correct": true, "because": "Änderungen isoliert"}, {"text": "Testbarkeit", "correct": true, "because": "Klare Aufgaben prüfbar"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Performance-Ziel"}, {"text": "Weniger Variablen", "correct": false, "because": "Unabhängig davon"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SRP trennt Logik von Darstellung. b) Es macht Code immer kürzer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kürze nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Single Responsibility Principle?', 4, '[{"text": "Aufgabentrennung", "correct": false, "because": "Kern des Prinzips"}, {"text": "Kohäsion", "correct": false, "because": "Stärkt Verantwortung"}, {"text": "Farbcodierung", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SRP mehr Klassen erzeugt?', 2, '[{"text": "Ja", "correct": true, "because": "Jede Aufgabe eine Klasse"}, {"text": "Nein", "correct": false, "because": "Trennung erhöht Anzahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel folgt dem Single Responsibility Principle?', 3, '[{"text": "Klasse nur für Datenbankzugriff", "correct": true, "because": "Eine Verantwortung"}, {"text": "Klasse für UI und Logik", "correct": false, "because": "Mehrere Aufgaben"}, {"text": "Klasse für Tests und Daten", "correct": false, "because": "Vermischte Rollen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördert das Single Responsibility Principle?', 5, '[{"text": "Modularität", "correct": true, "because": "Klar getrennte Einheiten"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Spezifische Aufgaben nutzbar"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Kein Performance-Fokus"}, {"text": "Weniger Zeilen", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) SRP reduziert Komplexität. b) Es ersetzt Modularisierung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzt Modularisierung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Single Responsibility Principle?', 4, '[{"text": "Klare Aufgaben", "correct": false, "because": "Kern des Prinzips"}, {"text": "Kohäsion", "correct": false, "because": "Stärkt Fokus"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist SRP ohne Planung möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Trennung erfordert Design"}, {"text": "Ja", "correct": false, "because": "Planung essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme löst das Single Responsibility Principle?', 4, '[{"text": "Hohe Kopplung", "correct": true, "because": "Trennt Verantwortungen"}, {"text": "Schwere Wartung", "correct": true, "because": "Änderungen einfacher"}, {"text": "Langsame Tests", "correct": false, "because": "Kein Testfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass SRP nur für Teams ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Solo nützlich"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Single Responsibility Principle?', 3, '[{"text": "Eine Aufgabe pro Klasse", "correct": true, "because": "Kernprinzip"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Viele Funktionen", "correct": false, "because": "Widerspricht SRP"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SRP fördert Wiederverwendung. b) Es garantiert Fehlerfreiheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlerfreiheit nicht Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das Single Responsibility Principle?', 5, '[{"text": "Mehr Klassen", "correct": true, "because": "Trennung erhöht Anzahl"}, {"text": "Höherer Planungsaufwand", "correct": true, "because": "Design nötig"}, {"text": "Langsamere Ausführung", "correct": false, "because": "Kein Performance-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Single Responsibility Principle unwichtig?', 3, '[{"text": "Aufgabenfokus", "correct": false, "because": "Kernprinzip"}, {"text": "Kohäsion", "correct": false, "because": "Stärkt Verantwortung"}, {"text": "UI-Design", "correct": true, "because": "Kein Code-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht SRP die Komplexität?', 3, '[{"text": "Nein", "correct": true, "because": "Vereinfacht durch Trennung"}, {"text": "Ja", "correct": false, "because": "Reduziert Komplexität"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SRP Tests erleichtert?', 2, '[{"text": "Ja", "correct": true, "because": "Isolierte Aufgaben prüfbar"}, {"text": "Nein", "correct": false, "because": "Testbarkeit steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ergänzt das Single Responsibility Principle?', 4, '[{"text": "Open Closed", "correct": true, "because": "Erweiterung ohne Änderung"}, {"text": "KISS", "correct": false, "because": "Allgemeiner Ansatz"}, {"text": "YAGNI", "correct": false, "because": "Anderer Fokus"}]');
